LOCALES = {"tr": TR, "en": EN, "de": DE}
KEYS = frozenset(TR)
assert all(frozenset(LOCALES[lang]) == KEYS for lang in UI_LANGS)


def t(key: str, lang: str = "tr") -> str:
    return LOCALES.get(lang, TR).get(key, key)


